using System;using System.Linq;using UnityEngine;using UnityEditor;
public static class ValidateOrganicForest {
 public static object Main(){if(!Application.isPlaying)throw new Exception("Requires Play Mode");var world=UnityEngine.Object.FindAnyObjectByType<ExplorationWorld>();int errors=ShaderUtil.GetShaderMessages(Shader.Find("Game/Realistic Forest Ground")).Count(m=>m.severity.ToString()=="Error");int rays=0;float mismatch=0;foreach(var soil in world.GetComponentsInChildren<SoftGroundRuts>())soil.Commit();
 foreach(var filter in world.GetComponentsInChildren<MeshFilter>()){
 var physical=filter.GetComponent<MeshCollider>();if(physical==null||!(filter.name=="Forest ground"||filter.name.StartsWith("Road adventure")))continue;var probe=new GameObject("Independent organic ground probe");probe.transform.SetPositionAndRotation(filter.transform.position,filter.transform.rotation);var visible=probe.AddComponent<MeshCollider>();visible.sharedMesh=filter.sharedMesh;try{var vertices=filter.sharedMesh.vertices;for(int i=0;i<vertices.Length;i+=Mathf.Max(1,vertices.Length/8)){var ray=new Ray(filter.transform.TransformPoint(vertices[i])+Vector3.up*3,Vector3.down);if(visible.Raycast(ray,out var a,6)&&physical.Raycast(ray,out var b,6)){mismatch=Mathf.Max(mismatch,Mathf.Abs(a.point.y-b.point.y));rays++;}}}finally{UnityEngine.Object.DestroyImmediate(probe);}}
 var road=world.Map.Roads.First(r=>r.adventure==0);var centre=road.points[6];var direction=(road.points[7]-road.points[5]).normalized;var side=new Vector2(direction.y,-direction.x);var roads=world.Map.Nearby(centre,100);float crown=ForestSurfaceModel.RoadRelief(world.Map,centre,roads),rut=ForestSurfaceModel.RoadRelief(world.Map,centre+side*.79f,roads);
 var details=world.GetComponentsInChildren<ExplorationUnderstory>();int grass=details.Sum(d=>d.GrassCount),shrubs=details.Sum(d=>d.ShrubCount);
 if(errors!=0||mismatch>.002f||rays<50||grass<1000||shrubs<100||crown-rut<.02f)throw new Exception("Organic forest validation failed");
 return new{success=true,shaderErrors=errors,independentRays=rays,maxMeshMismatch=mismatch,authoredRutBelowCrown=crown-rut,preparedGrassClumps=grass,preparedShrubClumps=shrubs,grassVariants=world.palette.grassClumps.Length,shrubVariants=world.palette.shrubClumps.Length,activeBogMeshes=world.GetComponentsInChildren<RainSoakedRoad>().Count(r=>r.name=="Road adventure 6")};
 }
}
